// Narrow filter: keep ONLY this report's attachments.
//
// The Gmail query is deliberately broad (sender + has:attachment + PDF) so no
// subject-string change can silently stop the feed. Routing happens HERE, on
// the LP report ID embedded in the attachment filename — the one machine-
// stable identifier LP emits.
//
// Every message in the poll and every attachment in each message is examined,
// so five reports landing in one 15-minute window all get processed: this
// workflow takes its own and leaves the rest to its siblings (a non-matching
// filename is that sibling's item, not a dropped one). A report type that
// stops arriving altogether is caught by the LP-MCP watchdog, which alerts per
// report type — that is the never-silent guarantee for this design.
const RE = /_134_/;
const out = [];
for (const item of $input.all()) {
  const bin = item.binary ?? {};
  for (const key of Object.keys(bin)) {
    const fileName = bin[key]?.fileName ?? '';
    if (!RE.test(fileName)) continue;
    out.push({
      json: { ...item.json, lp_report_id: '134', attachment_file_name: fileName },
      binary: { attachment_0: bin[key] },
    });
  }
}
return out;
